def f(a: int, b: int) -> int:
    """Returns 2 * min(abs(a), abs(b)) with the sign of a*b; returns 0 if either input is 0."""
    m = min(abs(a), abs(b))
    if a == 0 or b == 0:
        return 0
    return 2 * m if a * b > 0 else -2 * m

